    constructor(maxScore) {
        this.maxScore = maxScore;
    }

    processScore(rawScore) {
        // TODO: Delegate score validation to a ScoreValidator instance.
        // If the score is invalid, return an error message.
        if (typeof rawScore !== 'number' || rawScore < 0 || rawScore > this.maxScore) {
            console.log(`Error: Invalid score ${rawScore}. Score must be a number between 0 and ${this.maxScore}.`);
            return { error: `Invalid score ${rawScore}` };
        }

        // TODO: Delegate normalized score calculation to a NormalizedScoreCalculator instance.
        const normalizedScore = (rawScore / this.maxScore) * 100;

        const result = { raw: rawScore, normalized: parseFloat(normalizedScore.toFixed(2)) };
        console.log(`Raw Score: ${rawScore}, Normalized Score: ${result.normalized}`);
        return result;
    }
}

