class ScoreValidator {
    constructor(maxScore) {
        this.maxScore = maxScore;
    }

    isValid(score) {
        return typeof score === 'number' && score >= 0 && score <= this.maxScore;
    }
}

class NormalizedScoreCalculator {
    constructor(maxScore) {
        this.maxScore = maxScore;
    }

    calculate(rawScore) {
        return (rawScore / this.maxScore) * 100;
    }
}

class GameScoreProcessor {
    constructor(maxScore) {
        this.maxScore = maxScore;
        this.scoreValidator = new ScoreValidator(maxScore);
        this.normalizedScoreCalculator = new NormalizedScoreCalculator(maxScore);
    }

    processScore(rawScore) {
        if (!this.scoreValidator.isValid(rawScore)) {
            const errorMessage = `Error: Invalid score ${rawScore}. Score must be a number between 0 and ${this.maxScore}.`;
            console.log(errorMessage);
            return { error: errorMessage };
        }

        const normalizedScore = this.normalizedScoreCalculator.calculate(rawScore);

        const result = { raw: rawScore, normalized: parseFloat(normalizedScore.toFixed(2)) };
        console.log(`Raw Score: ${rawScore}, Normalized Score: ${result.normalized}`);
        return result;
    }
}

